ProjectALife = ProjectALife or {}
ProjectALife.DialogueShards = ProjectALife.DialogueShards or {}
ProjectALife.DialogueShards["radio_5"] = {
{"r1_d3_knox4_whistling_slow","scanner",3,3,8,18,1,{"Knox 4","Knox 4 to Knox County - Buckshot got out of the courthouse when the Guard truck came through the gate - Donna says it's my turn","Dispatch","Knox 4, it's not safe to go driving around after a dog","Knox 4","I'm not walking, I'm driving slow with the window down, whistling, he knows the whistle","Dispatch","Check in every fifteen minutes","Knox 4","Knox 4, still whistling - Main Street, headed out toward Otter Creek - no dog","Dispatch","Knox 4, Knox County, it's been twenty minutes","Dispatch","Knox 4, Donna says Buckshot came back on his own - he's in the basement eating somebody's sandwich, she says come on back now","Dispatch","Knox 4, the dog's home - come on back to the courthouse","Dispatch","I'll keep calling you, Knox 4"}},
{"r1_d3_riverside1_pager_911","scanner",3,3,6,20,2,{"Riverside 1","Riverside 1, dispatch, my wife's at the house with our two girls, she's been paging me nine-one-one for an hour","Dispatch","Riverside 1, I can't authorize you to leave your post - I'm county - you're city","Riverside 1","My chief's gone, my sergeant's gone, I'm asking you, Linda","Dispatch","Go home, Riverside 1","Riverside 1","Thank you","Dispatch","Riverside 1 is off duty at {time}, key up when you get there, so I know","Riverside 1","Riverside 1 - I'm home, the door was locked, they're up in the attic with the ladder pulled up - they're alright - they're alright","Dispatch","Good, stay there - that's an order from nobody"}},
{"r1_d3_knox15_blinker_open_mic","scanner",3,3,0,6,1,{"Dispatch","Unit with an open mic, you're tying up the channel - let off your button","Dispatch","Unit with the open mic, I can hear a car radio playing low and a turn signal clicking - let go of the button","Dispatch","Knox 15, if that's you, I can hear your blinker going - let off the button, honey","Knox 20","Knox 20, I'll try him car-to-car - Knox 15, Knox 20","Dispatch","Carrier dropped - Channel's clear - Knox 20, the last place I had him was Cedar Lane by the water tower","Knox 20","I'll drive Cedar at daylight, I'll look for a car with its blinker on"}},
{"r1_d3_knox20_found_car_note","scanner",3,3,7,16,1,{"Knox 20","Knox 20, Knox County, I found Knox 15's car on Cedar Lane, off the shoulder by the water tower","Knox 20","Engine's off, battery's about gone, the left blinker's still going, slow","Knox 20","His portable was wedged down between the seat and the console with the button pressed - that was your open mic","Knox 20","No sign of him, no blood in the car - shotgun's gone from the rack","Knox 20","I'm taking the portable, I'm leaving him a note on the dash telling him where we are","Dispatch","Copy - what did you write?","Knox 20","Courthouse - come home"}},
{"r1_d3_sheriff_orders_cot","scanner",3,3,9,14,2,{"Knox 1","Knox 1 to Knox County","Dispatch","Go ahead, Sheriff","Knox 1","Linda, how long have you been sitting at that console?","Dispatch","Since three o'clock Friday, Sheriff","Knox 1","This is an order - Peggy Tanner is coming in to sit the console, you go lie down on the cot in records for four hours","Dispatch","Sheriff, she doesn't know the radio","Knox 1","She knows how to push a button and write down what somebody tells her - so did you, once","Dispatch","Four hours","Knox 1","Four hours - Knox 1 to all units, if you need something in the next four hours, you ask Mrs. Tanner nicely","Console","Um, this is Knox County, this is Peggy Tanner - Linda's gone to lie down - please nobody get hurt"}},
{"r1_d3_peggy_good_ones","scanner",3,3,10,15,2,{"Knox 9","Knox 9 to Knox County - show me 10-8 from the county garage","Console","Knox 9, is 10-8 a good one or a bad one?","Knox 9","It's a good one, Mrs. Tanner, it means I'm available","Console","Oh, good, I've written it down - Knox 9, 10-8, county garage, good one","Hardin 12","Hardin 12, I'll be 10-97 at the courthouse in five with a load of blankets","Console","I don't see that one on the sheet Linda taped up - is it good?","Hardin 12","It means I'm arriving, ma'am","Console","Then I'll put coffee on - is there a number for that?","Knox 20","Knox 20, honey, there's no number for coffee, just put it on"}},
{"r1_d3_knox9_linden_street_note","scanner",3,3,15,21,2,{"Knox 9","Knox 9 to Knox County - Linda back on the console?","Dispatch","I'm here, Knox 9","Knox 9","I went by your place on Linden Street like you asked","Dispatch","Go ahead","Knox 9","House is locked up tight, your car's gone from the carport - no windows broken, no sign of anybody around it","Knox 9","There's a note taped inside the storm door, it says, went to Aunt Jo's - it's in your boy's handwriting, I believe","Dispatch","Aunt Jo's in Echo Creek","Knox 9","Then that's a direction, anyway, that's more than most folks have got","Dispatch","Thank you, Knox 9 - ten. 10-4","Knox 9","I left the note right where it was, in case he comes back by the house for something"}},
{"r1_d3_knox6_shotgun_rack","scanner",3,3,12,23,2,{"Knox 6","Knox County, this is Knox 6 - show me 10-8, darlin' - hahaha","Dispatch","Unit identifying as Knox 6, that unit has been off duty since Friday - identify yourself","Knox 6","Found his car behind the Rosewood jail with the keys in it - real nice car, smells like old coffee and cheap aftershave","Knox 6","We're the two from the prison transfer, the jailer said we had to stay put, the jailer isn't saying much of anything now","Dispatch","Whoever has that radio, that vehicle is county property, and you are committing a felony","Knox 6","Write me a ticket - hey, lady, what's the ten-code for we got the shotgun out of the rack?","Knox 20","Knox 20 to all units - Knox 6's car is stolen, two escapees, armed with a department shotgun, last seen Rosewood, do not approach alone","Knox 6","Aw, Sarge, don't be like that, we'll bring it back with a full tank","Dispatch","All units, disregard any traffic from Knox 6, switch to channel two for county business"}},
{"r1_d3_rosewood5_menu_floor","scanner",3,3,9,18,1,{"Rosewood 5","Rosewood 5 to Knox County, I'm at the Rosewood jail","Rosewood 5","Sally port's standing open, keys are still in the lock on the lockdown cell - that cell's empty","Dispatch","Any sign of the jailer?","Rosewood 5","Arliss is in the booking room, I'm not going to say more than that on the air","Rosewood 5","His lunch menu's on the floor, the one with his release order on the back, somebody stepped on it","Dispatch","Copy, Rosewood 5 - do you want me to log it?","Rosewood 5","Log that he did it by the book, he wrote it down and he signed it, I'm taking the menu with me"}},
{"r1_d3_warden_liaison_takes_net","scanner",3,3,13,22,1,{"Warden Liaison","All civilian agencies on this frequency, this is Warden Liaison, United States Army","Warden Liaison","This frequency is now under military control, civilian traffic is limited to emergency traffic only - acknowledge","Knox 20","Knox 20, acknowledged - who do we call if we need help from you?","Warden Liaison","You do not call this station for assistance, maintain your positions - keep civilians away from the line - Warden Liaison out","Knox 11","Knox 11 copies, real nice talking to you","Knox 20","Knox 11","Knox 11","Sorry, Sarge - Knox 11, emergency traffic only"}},
{"r1_d3_medic3_baby_rose","scanner",3,3,10,21,3,{"Medic 3","Medic 3, anybody on this channel, we're out of fuel on Louisville Road, a mile west of the rail crossing","Medic 3","Two crew and one patient, and she's not bitten, she's having a baby","Dispatch","Medic 3, Knox County, I copy - how far along is she?","Medic 3","Far enough that she's yelling at me to get off the radio","Hardin 12","Hardin 12, I'm on Louisville Road - six minutes","Medic 3","Hardin 12, don't hurry on our account, we're not going anywhere - the baby might be","Medic 3","Knox County, Medic 3 - show one additional patient - a girl, seven pounds, give or take, mother's doing fine","Dispatch","Medic 3, does she have a name?","Medic 3","Mom says she's naming her after the deputy who pulled up with his lights on","Hardin 12","Hardin 12 - Ma'am, please tell her Russ is a terrible name for a little girl","Medic 3","Mom says she'll settle for Rose"}},
{"r1_d3_trooper422_hat_blanket","scanner",3,3,7,17,2,{"Trooper 422","Post 4, 422, I'm at the old 31W checkpoint","Post 4","Go ahead, 422","Trooper 422","The Army's pulled back about half a mile. Road's empty here... except for all these shoes","Trooper 422","410's car is parked on the shoulder with the door open - his hat's on the seat, he's not here","Post 4","Copy, 422 - anything else?","Trooper 422","There's a baby blanket folded up on his hood - folded neat, somebody took the time to fold it","Post 4","Copy - bring the hat in, 422","Trooper 422","Bringing the hat"}},
{"r1_d3_station21_onions","scanner",3,3,9,19,1,{"Station 21","Station 21 to Knox County","Dispatch","Go ahead, Station 21","Station 21","We've got the bay doors down and twenty-six neighbors on cots between the engines","Station 21","The generator's good for three days - water's good, one of the neighbors cooked for the Army at Fort Knox for twenty years, and he's taken over the kitchen","Dispatch","Do you need anything I can send?","Station 21","He says onions, any unit that comes across onions, he'll trade a hot supper for them","Knox 11","Knox 11, I've got a sack of onions in my trunk from the produce stand on 1638 - paid the man for them too","Station 21","Knox 11, you are a hero to this firehouse","Knox 11","First time for everything"}},
{"r1_d3_sheriff_courthouse_open","scanner",3,3,6,12,3,{"Marty","Sheriff came on his own channel this morning, talking to all of us, not just his deputies... so here he is","Knox 1","Knox 1 to all units, and anybody who can hear this channel on a scanner","Knox 1","This is Sheriff Wendell Groves, courthouse in Rosewood is open - we got a doctor and water, deputies on the doors","Knox 1","If you can get here, come in daylight, come slow, and come with your hands where my people can see them","Knox 1","We'll look at your arms at the door, I'm sorry about that - we'll look at mine too","Knox 1","If you can't get here, stay where you are and stay quiet - somebody will come by, I can't promise you when - Knox 1 out","Marty","That was Wendell Groves, he bought hay off me for his daughter's horse for eleven years and never once haggled - if he says come in slow, come in slow"}},
{"r1_d3_coroner_count_212","scanner",3,3,16,23,1,{"Coroner","Coroner to Knox County, for the record, my count stands at two hundred and twelve reported deceased since Friday","Coroner","That's the ones that got called in, I stopped being able to go out to them yesterday","Dispatch","Copy, coroner - it's logged","Coroner","I'd like it logged every day, if you would, somebody ought to keep the number","Dispatch","I'll log it every day, Doc","Coroner","Thank you, I'm going home to lie down now - my wife's been poorly since Saturday","Dispatch","Take care of her","Coroner","She's taken care of, I'll check in tomorrow with the count"}},
{"r1_d3_westpoint2_lonnie_over","scanner",3,3,9,20,1,{"West Point 2","West Point 2 to Knox County, I've got a civilian riding with me - he's helping","Dispatch","What's his name, West Point 2?","West Point 2","Stand by, I'll let him tell you","Civilian","Hello? Lonnie Sturgill, I pump septic tanks - the officer let me ride because I've got a bigger gun than he does","Dispatch","Welcome aboard, Lonnie - keep your hands off the light switches","Civilian","Yes ma'am, do I say over?","Dispatch","Nobody says over on this channel, Lonnie","Civilian","Okay, over","West Point 2","I'm taking the radio back now"}},
{"r1_d3_post4_fish_sticks","scanner",3,3,8,20,1,{"Post 4","Post 4 to all Post 4 units, commercial power is down at the post, we're on generator with a crew of three","Post 4","Troopers who can't return to post, find a safe location and check in by radio every four hours","Trooper 435","435, Post, checking in from the Irvington grade school, nine civilians with me - we're in the cafeteria","Post 4","Copy, 435 - how are you set?","Trooper 435","There's a walk-in freezer full of fish sticks and tater tots - we're set for about a year, if nobody minds fish sticks","Post 4","Nobody minds, 435","Trooper 422","422, Post, I'm with 435's bunch now, I mind a little"}},
{"r1_d3_robert_team_drops_home","scanner",3,3,6,19,2,{"6-Robert-23","6-Robert-23 to any SWAT unit on mutual aid","6-Robert-21","Robert-21, go","6-Robert-23","The command post is gone, the lieutenant's gone, it's you, me, and Deacon in the van - what do you want to do?","6-Robert-21","Take everybody home, one house at a time - Deacon first, he's closest","6-Robert-23","Copy - Deacon's place is off Dixie in Valley Station - pulling up","6-Robert-23","His wife and kids are on the porch with suitcases - they were waiting on him, he's out of the van - he's saluting us - idiot","6-Robert-21","Salute him back - who's next?","6-Robert-23","You are - then me, then there's nobody left to drive the van","6-Robert-21","Leave the keys in it, somebody's going to need a van"}},
{"r1_d3_hardin12_bo_driver_door","scanner",3,3,12,20,1,{"Hardin 12","Hardin 12, Knox County, I went back to the West Point High lot","Dispatch","Go ahead, Hardin 12","Hardin 12","Knox 12's car is still there, I got the dog out, he came right to me","Hardin 12","I looked around the gym doors as long as I could","Dispatch","Copy, Hardin 12","Hardin 12","The dog won't get in my car, he keeps going back and sitting down by the driver's door of Knox 12's unit","Hardin 12","I'm going to sit here with him a while - show me busy"}},
{"r1_d3_knox11_icu_high_beams","scanner",3,3,19,23,2,{"Knox 11","Knox 11, Knox County, I'm on the hill across from the hospital with binoculars","Dispatch","Go ahead","Knox 11","The parking lot's full of them - hundreds, the lobby doors are down","Knox 11","Third floor, the ICU end, somebody's in the window with a white towel","Dispatch","Can you get to them?","Knox 11","Negative, not with one car - I flashed my high beams twice","Knox 11","They flashed the room lights back twice, they're alive up there","Dispatch","I'm writing it down, Knox 11, third floor, ICU end, towel in the window, lights twice"}},
{"r1_d3_blackjack23_boxes_hover","scanner",3,3,8,17,1,{"Blackjack 23","Any station this frequency, this is Army helicopter Blackjack 2-3 - I have supplies for the Knox County courthouse","Knox 11","Blackjack 2-3, Knox 11, go ahead","Blackjack 23","Knox 11, we are not authorized to land inside the line - we'll come to a low hover over the courthouse lot and push the boxes out - mark the spot with your vehicle","Knox 11","Copy, I'll be in the lot with my lights on - watch the power lines on the east side","Blackjack 23","Copy power lines - clear the lot of personnel, the rotor wash will flatten anything loose","Knox 11","Lot's clear, just so you know, that noise is going to bring every one of them in town","Blackjack 23","Understood, we'll be over you thirty seconds, boxes are going out now","Blackjack 23","All boxes out - climbing, good luck, Knox 11","Knox 11","Dispatch, it's four boxes of bandages and a box of body bags - and somebody taped a note on top that says good luck again"}},
{"r1_d3_car_to_car_tomatoes","scanner",3,3,1,4,1,{"Knox 11","Knox 11 to Hardin 12, car-to-car - you awake over there?","Hardin 12","Hardin 12, awake is a strong word","Knox 11","I'm parked on the hill by the grain elevator watching the road - figured I'd talk before I start seeing things","Hardin 12","I'm at the courthouse gate - what do you want to talk about?","Knox 11","Anything that isn't this - what would you be doing if it was a regular Monday?","Hardin 12","Picking tomatoes before work, my wife plants twelve plants every year and says she'll plant six next year - every year","Knox 11","How many this year?","Hardin 12","Fourteen, they'd be coming in about now","Knox 11","Hold on, I've got headlights coming up the county road behind me - Knox 11 is going back to work, thanks for the tomatoes"}},
{"r2_d3_colonel_hears_marty","military",3,4,0,23,2,{"Warden-2","Warden-6, Warden-2 - be advised, a civilian FM station on ninety-nine point six is rebroadcasting this net - the voice says he owns a feed store in March Ridge, over","Warden-6","How much of it, over?","Warden-2","Checkpoint counts, the Packhorse traffic, the church van, he plays it back and explains our terms to them - very politely, over","Warden-6","Can we take the transmitter off the air, over?","Warden-2","Not without a patrol into March Ridge, sir, and I don't have a patrol to send, over","Warden-6","Then we move, all Warden stations shift to the alternate frequency at 1800, over","Hatchet-6","Warden-6, Hatchet-6 - Thoroughbred's old sets can't reach the alternate, we'll lose the Brandenburg road, over","Warden-6","Then Thoroughbred stays on this frequency and says nothing worth hearing - Warden-6, out","Marty","That was about me, I'm the feed store owner, I'll admit my hands are shaking a little, being discussed by the United States Army","Marty","If they move to another frequency, I'll turn this dial until I find them - I have a lot of time and not much else to spend it on"}},
{"r2_d3_truck_seven_fuel_pump","military",3,4,7,19,1,{"Warden Main","Bluejay 2-4, Warden Main, request you search for a missing convoy, nine vehicles, last reported at the Muldraugh overpass, over","Bluejay 2-4","Warden Main, I have forty minutes of fuel and a tasking from brigade to look at the bridge - brigade outranks you, over","Warden Main","Understood - can you fly the county road to Riverside on your way back, over?","Bluejay 2-4","Wilco, it isn't on my way back, I'll make it on my way back, over","Bluejay 2-4","Warden Main, Bluejay 2-4, county road to Riverside, negative convoy, one deuce-and-a-half in the ditch at the creek crossing, hood up, over","Warden Main","Any markings, over?","Bluejay 2-4","Chalk on the driver's door - number seven, somebody wrote fuel pump under the number, over","Warden Main","That's theirs, they left it right where they said they would - continue, over","Bluejay 2-4","I'm at bingo fuel, Warden Main, returning to base - sorry - Bluejay 2-4, out"}},
{"r2_d3_nine_line_refused","military",3,5,0,23,2,{"Striker-1-6","Dustoff, Dustoff, this is Striker-1-6, nine-line, stand by, over","Dustoff 2-1","Striker-1-6, Dustoff 2-1, send your nine-line, over","Striker-1-6","Line one, grid 4187 2204, line two, this frequency, Striker-1-6, line three, one Bravo - line four, Alpha, line five, one litter, over","Striker-1-6","Line six, Echo, line seven, smoke - line eight, one US military, line nine, see remarks, over","Dustoff 2-1","Copy through line nine, send remarks, over","Striker-1-6","Specialist, twenty years old, deep laceration of the forearm, arterial, tourniquet on, happened hand to hand at the wire, over","Dustoff 2-1","Striker-1-6, was the injury caused by a Category Three, over?","Striker-1-6","It was a scratch, it was the hand, not the teeth - he needs a surgeon inside the hour, over","Dustoff 2-1","Striker-1-6, I'm sorry, standing order from Warden-6, no lift for any injury caused by a Category Three - mission refused, over","Striker-1-6","Then get me a surgeon who'll talk my medic through it on this net, over","Dustoff 2-1","Stand by, I'll find you somebody - Dustoff 2-1, wait out"}},
{"r2_d3_surgeon_talks_medic","military",3,5,0,23,1,{"Task Force Surgeon","Striker-1-6, this is the task force surgeon - put your medic on the handset, over","Striker Medic","Sir, Specialist Ocampo, medic - go ahead, over","Task Force Surgeon","Ocampo, is the tourniquet holding, over?","Striker Medic","Holding, sir, it's been on forty minutes - he keeps asking me to loosen it, over","Task Force Surgeon","Don't loosen it - is he warm to the touch, over?","Striker Medic","He's warm, sir, it's ninety-five degrees in this tent, everybody's warm, over","Task Force Surgeon","Understood - take his temperature under the arm every fifteen minutes and write it on the back of his hand in marker - read me each number, over","Striker Medic","Roger, first number is one hundred point four, over","Task Force Surgeon","Copy one hundred point four, that can be the heat, son, next number in fifteen, over","Striker Medic","Next number in fifteen - Sir, he's asking if he can have his canteen, over","Task Force Surgeon","Give him the canteen, task force surgeon, out"}},
{"r2_d3_bridge_boots_lined_up","military",3,6,5,21,1,{"Lockbox-1-6","Lockbox-6, TCP 1, single vehicle, blue pickup, northbound on the bridge deck at walking speed - passing the fifth light pole, over","Lockbox-6","Start the loudspeaker at the fifth pole, the final warning point stays the burned-out car at the second pole, over","Lockbox-1-6","Loudspeaker's on, he's still coming - fourth pole, the driver has his arm out the window waving a white towel, over","Lockbox-6","One warning shot into the deck ahead of him at the third pole - only one, over","Lockbox-1-6","One warning shot fired, vehicle stopped at the third pole - he's getting out, he's walking, over","Lockbox-6","Loudspeaker - tell him the burned car is the line and if he passes it he dies - use those words, over","Lockbox-1-6","Told him in those words, he sat down in the road a car length short of it, over","Lockbox-6","Is he armed, over?","Lockbox-1-6","Negative, he's taking his boots off, he's lining them up side by side next to him, over","Lockbox-6","Watch him, nobody fires while he's sitting - Lockbox-6, out"}},
{"r2_d3_beckham_from_paducah","military",3,6,0,23,1,{"Hatchet-2-3","Any station, any station, this is Hatchet-2-3, I need help at the Ekron firehouse, over","Warden Main","Station calling, Warden Main, authenticate Hotel Juliet, over","Hatchet-2-3","I don't have the card, staff Sergeant Moss had the card, he kept it in his vest, and he's, he isn't, over","Warden Main","Station calling, without authentication I can't confirm you're Hatchet-2-3, over","Hatchet-2-3","I'm Private First Class Troy Beckham, I'm from Paducah - my drill sergeant was Staff Sergeant Oakes - ask anybody, over","Warden Main","Hatchet-6, Warden Main - do you have a Beckham in second platoon, over?","Hatchet-6","Affirmative - Beckham, second squad, from Paducah, over","Warden Main","Beckham, I believe you, I have nothing to send to Ekron - stay in the firehouse, keep the bay doors down, and stay off the radio unless they get in, over","Hatchet-2-3","Roger, thank you for believing me, that was the part I needed, over"}},
{"r2_d3_no_thursday_buses","military",3,5,8,20,1,{"Unit 14","Army checkpoint on the Brandenburg road, this is sheriff's Unit 14 on your frequency - folks in Irvington say buses come Thursday to take everybody to Louisville - is that yours, over?","Hatchet-6","Unit 14, Hatchet-6 - negative, the Army has no evacuation planned out of this county, over","Unit 14","Then who's telling them Thursday, over?","Hatchet-6","Unknown - not us - tell them to stay in their homes, over","Unit 14","I have eighty people on the Irvington school lawn sitting on suitcases waiting for Thursday, over","Hatchet-6","Then you'll have to be the one who tells them, over","Unit 14","10-4, figured it'd be me - unit 14 clear"}},
{"r2_mis_railroad_whisper","military_mistake",3,8,22,4,1,{"Hale","If we go at three, nobody's awake but Sims, and Sims won't say anything","Mott","Go where, though? My mom's in Radcliff, that's the far side of the whole line","Hale","We walk the railroad tracks, nobody puts a checkpoint on railroad tracks","Mott","They don't need to, I saw a bunch of those things walking the ties yesterday, single file, like they had a ticket","Anvil-3-7","Hale - Mott, this is Sergeant Wills, your handset is keyed, and I'm standing forty feet behind you","Hale","Sergeant, we weren't really going to go","Anvil-3-7","I know - Unkey - come over to my hole, both of you, I've got coffee, and I'd rather hear the rest of this in person"}},
{"r2_mis_radio_lost_fill","military_mistake",3,7,0,23,1,{"Crowbar-3-6","Warden Main, Crowbar-3-6, in the clear, our radio dumped its fill when we swapped the battery - we can't get on the secure net, over","Warden Main","Crowbar-3-6, stop transmitting in the clear, drive to TCP 3 and get a new fill, over","Crowbar-3-6","TCP 3 is twelve miles and I have a quarter tank - can you read me the fill over the radio, over?","Warden Main","Negative, that's the entire point of a fill, nobody reads it over the radio, over","Crowbar-3-6","Then how am I supposed to talk to you, over?","Warden Main","You're doing it right now, so is everybody with a scanner - drive to TCP 3 - Warden Main, out","Marty","For those wondering, I don't know what a fill is either - I gather it's something you aren't supposed to read over the radio"}},
{"r2_mis_last_battery_roof","military_mistake",3,8,9,18,1,{"Striker-3-1","Striker-3-6, Striker-3-1 - battery's dying, this is the last one, sending all my status at once, over","Striker-3-1","Six personnel, two wounded, walking, about thirty rounds a man, water through tomorrow - we're on the roof of the Rosewood post office, over","Striker-3-6","Striker-3-1, Striker-3-6 - stop, you just sent your location in the clear, over","Striker-3-1","Sir, I know, at this point I'd rather everybody knows where we are than nobody does, over","Striker-3-6","Understood - save the battery, transmit only at noon, ten seconds, every day, over","Striker-3-1","Roger, noon, ten seconds, if you don't hear me at noon, it was the battery, over","Striker-3-6","Roger, it'll be the battery - Striker-3-6, out"}},
{"r2_mis_counting_to_five_hundred","military_mistake",3,9,22,4,1,{"Warden Main","All stations, Warden Main, somebody has a stuck handset and the net is blocked - check your handsets, over","Stuck Handset","They went past the truck- don't move, count to five hundred with me","Stuck Handset","Mama, I'm sorry about the car, I know you told me - I know you told me about the car","Hatchet-7","Warden Main, Hatchet-7 on the alternate, that voice is Specialist Grubb at the east post, he's lying on his handset, over","Warden Main","Hatchet-7, can anyone get to him, over?","Hatchet-7","I'm going, it's two hundred meters - if he's lying on the handset he's lying still, and that's exactly what he ought to be doing, over","Stuck Handset","Four hundred ninety-nine - five hundred - okay - start over - one","Hatchet-7","Warden Main, Hatchet-7, I have Grubb, he's not bitten - he's alright, he keeps asking me about his car, over"}},
{"r2_mis_speaker_patched","military_mistake",3,7,7,20,1,{"Lockbox-1-6","Lockbox-6, Lockbox-1-6 - how many rounds do we have left for the bridge, over?","Lockbox-6","Lockbox-1-6, about four hundred - why is my voice echoing, over?","Lockbox-1-2","Sir, Lockbox-1-2, the handset's patched into the loudspeaker, everything you say is going out across the bridge, over","Lockbox-6","Unpatch it - now","Lockbox-1-6","Unpatched - Sir, the people out on the deck all stopped walking - they heard the number, over","Lockbox-6","Understood - what are they doing, over?","Lockbox-1-6","Counting themselves, sir, a man is walking down the line with his finger out, counting heads, over","Lockbox-6","Put the speaker back on the approved text - fifth pole - now - Lockbox-6, out"}},
{"r2_mis_pickle_password","military_mistake",3,7,19,2,1,{"Hatchet-2-6","All Hatchet-2 stations, tonight's challenge is Thunder, password is Pickle, over","Hatchet-2-7","Hatchet-2-6, you just sent challenge and password in the clear, over","Hatchet-2-6","Roger - disregard, challenge and password will come by runner, over","Hatchet-2-4","Hatchet-2-6, Hatchet-2-4, civilian at the wire, over","Hatchet-2-6","Challenge him, over","Hatchet-2-4","I challenged him, he said Pickle, sir - then he said he owns a scanner, and his grandmother needs her heart pills, over","Hatchet-2-6","Stand by","Hatchet-2-6","Hatchet-2-4, have him hold up the empty pill bottle and read me the name on it - nobody crosses the wire, over"}},
{"r2_d3_marty_lamp_off","military",3,4,21,2,2,{"Crowbar-2-4","Crowbar-2-6, Crowbar-2-4, movement on the main road in March Ridge, heading south past the feed store - about thirty, over","Crowbar-2-6","Roger thirty - Category Three, over?","Crowbar-2-4","Affirmative, walking down the middle of the road - one of them keeps stopping to look in the storefront windows, over","Crowbar-2-6","Do not engage in town - Observe and report, over","Marty","I'd like to say, very calmly, that there is only one feed store in March Ridge, and I am inside it","Marty","I've turned off the lamp, I'm going to stop talking for a while - I'll leave the transmitter on so you know I'm still here","Crowbar-2-4","Crowbar-2-6, Crowbar-2-4, group has passed the feed store and continues south - nothing went inside, over","Marty","Thank you, Crowbar-2-4, you'll never hear me say it, thank you anyway"}},
{"r2_mis_canteen_in_the_fog","military_mistake",3,7,4,8,1,{"Anvil-3-4","Cease fire! Cease fire! Friendly, friendly, Anvil-3 patrol coming in up the creek bed, over!","Anvil-3-6","All Anvil-3 stations, cease fire - check fire, that is our patrol, over","Anvil-3-2","Anvil-3-6, Anvil-3-2, nobody told us a patrol was out on the creek - they came up out of the fog walking slow with their arms hanging, over","Anvil-3-4","Because we're tired, Anvil-3-2! We walk slow because we've been walking since four!","Anvil-3-6","Anvil-3-4, casualties, over?","Anvil-3-4","Negative, one round through Hensley's canteen - he's more upset about the water, over","Anvil-3-6","Roger, from now on every patrol comes in waving a chemlight over its head and calling out its name - every patrol, over","Anvil-3-2","Roger - Sir, Hensley wants to know if he gets a new canteen, and he wants the man who shot it to fill it, over"}},
{"r2_mis_okay_not_kia","military_mistake",3,7,0,23,1,{"Hatchet-3-6","Hatchet-6, Hatchet-3-6, contact at the co-op, broken off - Wyatt and Combs are okay, over","Hatchet-6","Say again, Wyatt and Combs K-I-A, over?","Hatchet-3-6","Affirmative, Wyatt and Combs, over","Hatchet-6","Roger - I'm sorry - Warden Main, Hatchet-6, two killed in action at the co-op, over","Hatchet Overwatch","Hatchet-6, Overwatch, two figures walking in from the co-op - slow, in our uniforms - request permission to engage, over","Hatchet-3-6","Negative! Negative! That's Wyatt and Combs! I said okay! Oscar Kilo, okay, over!","Hatchet-6","All Hatchet stations, hold fire - Warden Main, Hatchet-6, correction, two killed is two okay, over","Warden Main","Roger, correction - Hatchet-6, from now on you spell everything, over"}},
{"r3_so_d3_feed_tickets","sign_on",3,4,5,8,4,{"Marty","Good morning, ninety-nine point six, March Ridge, this is Marty Colburn","Marty","I wrote down what I wanted to say on the backs of feed tickets last night so I wouldn't ramble - I'm going to read them in order","Marty","Ticket one, it is {weekday}, {date}, the time is {time}","Marty","Ticket two, the power is out on my end of March Ridge - I'm on a generator, so I'll be on the air in blocks, not all day","Marty","Ticket three says 'don't sound scared.' I'm going to skip ticket three","Marty","Ticket four - stay with me for what came over the scanner overnight"}},
{"r3_so_d3_paper_rattle","sign_on",3,7,5,7,1,{"Marty","This is ninety-nine point six, good morning, if it is one","Marty","You may hear paper rattling, that's my hands - I've decided that's normal the first few times, since there's nobody here to tell me different","Marty","Last night there was shooting from the direction of the school - it went on about twenty minutes, and then it stopped all at once","Marty","I don't know who was shooting, or at what, and I'm not going to guess on the air","Marty","What I can tell you is I'm here, the generator started on the second pull, and the coffee is terrible"}},
{"r3_so_d3_red_sunrise","sign_on",3,7,5,6,1,{"Marty","It's {time}, and the sun's coming up red over the grain bin - that's smoke in the air, from the north, I believe - Louisville direction","Marty","I want to start by saying the Army trucks that went through here on Saturday have not come back through","Marty","People have asked me if that means they're coming back - I'd like to know that myself","Marty","This is Marty Colburn, before you open a door this morning, look out every window you've got - not just the front"}},
{"r3_sf_d3_hammer_walk","sign_off",3,5,22,2,1,{"Marty","Before I sign off I'm going to do what I've done every night for thirty years, which is walk the store and check the locks","Marty","I'll be doing it with a claw hammer in my hand tonight - that part's new","Marty","Do your own walk - every door, the basement door and the one off the garage, the ones people forget","Marty","Ninety-nine point six is going off the air, six o'clock tomorrow, Lord willing"}},
{"r3_sf_d3_dolly_introduced","sign_off",3,7,22,2,1,{"Marty","Last thing tonight, a couple of you who stopped by asked about the cat you can hear on the air sometimes","Marty","Her name is Dolly, she's the store cat, she keeps the mice out of the feed and has never once done a thing I asked her","Marty","She's asleep on top of the transmitter right now because it's warm - so if we go off the air all of a sudden, that's on her","Marty","Good night, everybody - Dolly has no comment, ninety-nine point six, signing off"}},
{"r3_host_d3_scanner_explained","host",3,5,0,23,1,{"Marty","A word about the scanner, since I'll be reading off it","Marty","A scanner only listens, it hops between the sheriff, the state police, the fire departments, whatever's keyed up - I sit here and write down what comes through","Marty","I can't talk back to any of them, they can't hear me - I've tried hollering at it anyway, and I'll admit that to you","Marty","Last night it was mostly one deputy asking for somebody to meet him on Rosewood Road - he asked for about an hour, nobody answered him","Marty","I don't want to say more about that one, the water instructions are on the half hour"}},
{"r3_host_d3_ditch","host",3,7,20,23,1,{"Marty","I'm going to talk quieter for a while, the window's open, it's near ninety in this back office, and I don't know what's outside listening","Marty","If you have to lean in close to hear me, that's alright - lean in","Marty","Around suppertime there were three of them in the ditch across the road - they weren't doing anything, just standing up in the ditch","Marty","They're gone now, I watched them walk off toward the creek, I kept watching a long time after I couldn't see them anymore"}},
{"r3_host_d3_iowa_flood","host",3,6,0,23,1,{"Marty","The last thing I remember on the evening news before all this was the flooding out in Iowa - whole towns sitting in the river","Marty","I remember saying to my wife, those poor people, I put twenty dollars in the flood collection at church","Marty","I've been wondering whether anybody out in Iowa is putting twenty dollars in a plate for us - probably not, they've got the river in their living rooms","Marty","I suppose it's just our turn, is all"}},
{"r3_ins_d3_bleach_drops","instruction",3,7,5,12,3,{"Marty","Water questions again. If you don't know what's in it, don't pretend a clear bottle makes it safe","Marty","Don't pour bleach into drinking water and hope for the best","Marty","I'm not reading out a kitchen recipe for chemicals. Find water you can actually use","Marty","And keep fuel and cleaning fluids away from it. Label your containers"}},
{"r3_ins_d3_batteries","instruction",3,7,0,23,1,{"Marty","For those of you listening on batteries, which is most of you, a few things that'll stretch them","Marty","Turn the volume down to where you can just barely hear - loud eats batteries, and loud carries out the window","Marty","Turn the radio off between my hours, I'll always tell you when I'm coming back, so you don't have to sit there waiting with it on","Marty","When they're about dead, take them out and hold them in your hands, or keep them in your pocket a while - you'll get a little more - not much - a little"}},
{"r3_ins_d3_two_fingers","instruction",3,6,0,23,1,{"Marty","A lot of you are nailing plywood over your windows - good, here's what I've seen go wrong this week","Marty","Don't board the whole ground floor so tight you can't see out - you need to know what's in the yard before you open a door","Marty","Leave a gap about two fingers wide at eye level, on at least one window on every side of the house","Marty","And don't nail the back door shut, every house needs two ways out, a fire marshal told me that thirty years ago, and it still counts"}},
{"r3_ins_d3_cuts_not_bites","instruction",3,7,0,23,1,{"Marty","I sell a good deal of wound spray for livestock, and folks have asked if it works on people - please don't","Marty","For a cut, and I mean a cut, not a bite: wash it with boiled water and soap - press a clean cloth on it till it quits - keep it covered and dry","Marty","If it goes red and hot, and the red starts running out from it in lines, that's infection, and you need an antibiotic I can't hand you over the radio","Marty","What I'm saying is be careful with knives, there's no emergency room open right now to be careless toward"}},
{"r3_wx_d3_cattle_lying_down","weather",3,5,5,10,1,{"Marty","Weather for {weekday}, the barometer dropped a good bit overnight, and the cattle across the road are all lying down in the low corner of the field","Marty","The old men who sat in this store would tell you that means rain - the old men who sat in this store were right about half the time","Marty","If it does rain, set out every bucket and pot you own under the downspouts - pull the leaves out of the gutters if you can do it from a window","Marty","Don't get on the roof, I heard a man fell off his roof Monday trying to see down the road - that's the weather"}},
{"r3_mb_d3_corkboard","music_bridge",3,6,0,23,1,{"Marty","In place of a song, which I don't have, I'm going to read you the bulletin board by my register - consider it the top of the charts","Marty","Beagle pups, free to a good home, call after five - square bales, two-fifty a bale, you haul, lost, a green thermos, reward if returned","Marty","Wanted, a used push mower, doesn't need to be pretty - piano lessons for beginners, Mrs. Ogle, reasonable rates","Marty","And the ice cream social at the Baptist church, Saturday, July seventeenth - bring your own churn","Marty","I'm going to leave that one pinned up - back in a minute"}},
{"r3_sil_d3_generator_cough","silence",3,7,0,23,1,{"99.6 FM","(Static)","Marty","Sorry, that was the generator coughing - I'm back - it's back, we're both back"}},
{"r3_sil_d3_purring","silence",3,7,23,4,1,{"99.6 FM","(A carrier with nothing on it, somewhere close to the microphone, a cat is purring)"}},
{"r4_sad_tooth_quarter","caller_story_sad",3,8,19,23,1,{"Marty","Evening, it's Marty at the feed store in March Ridge, we have a caller - go ahead","Caller - Renee","My son lost a tooth last Thursday - bottom front, he was so proud he walked around with it in a sandwich bag","Caller - Renee","His daddy had him for the weekend, they live up in Valley Station, he took the tooth with him to show his daddy","Caller - Renee","He was supposed to bring it back Sunday night so it could go under his own pillow","Caller - Renee","I got a silver dollar from the bank for it - a real one, heavy, I was going to spoil him","Marty","That's a good tooth fairy","Caller - Renee","It's still on his pillow - the dollar, I make his bed every morning around it","Caller - Renee","Tooth fairy don't come if the tooth isn't there, everybody knows that, so it just sits","Marty","(Marty starts to say something, stops, and the line stays quiet)","Caller - Renee","Okay, thank you for letting me talk - y'all be careful"}},
{"r4_sad_mail_eleven_forty","caller_story_sad",3,8,9,17,1,{"Caller - Harold","Good morning - Harold Tate, Ekron, retired from the railroad - I don't usually talk on the radio","Marty","Morning, Mr. Tate, me neither, until Sunday","Caller - Harold","Our mail carrier is a lady named Bev - twenty-two years, she comes by at eleven-forty every day but Sunday","Caller - Harold","You could set a clock by her, my wife used to - Bev honks twice if there's a package","Caller - Harold","Friday she brought my pension check and a seed catalog - said it was too hot to breathe, see you Saturday","Caller - Harold","I've been walking down to the box at eleven-forty every day since - it's a long driveway, my knee isn't good","Caller - Harold","I know she's not coming, I'm not a fool - I just don't want her to pull up and find nobody there","Caller - Harold","I put a jar of ice water in the box for her - well, it was ice water","Marty","(A pause on the line, somewhere in the studio a fan clicks)","Marty","Thank you, Mr. Tate"}},
{"r4_sad_rotary_louisville","caller_story_sad",3,8,20,23,1,{"Caller - Carla","Is it okay if I don't say much about myself?","Marty","That's fine, that's more than fine","Caller - Carla","The phone in my kitchen's dead, no dial tone since Sunday - I pick it up anyway","Caller - Carla","My sister's number in Louisville, I dial it, it's an old rotary, so you hear it go round and come back","Caller - Carla","Her number has two nines in it, those take the longest - I used to hate those nines when I was a teenager on that phone","Caller - Carla","Now I wait for them, I dial it slow so they take even longer","Caller - Carla","Then I hold the phone for a bit, and I hang it up, and I wipe the counter","Marty","(Marty is quiet)","Caller - Carla","Sorry, I don't know what I wanted from you, I think I just wanted to dial something that answers","Marty","This one answers - any time"}},
{"r4_sad_dairy_cows","caller_story_sad",3,8,6,20,1,{"Marty","Knox County Radio - go ahead, caller, you're on","Caller - Jolene","You're the feed store, you'll know this - how often does a milk cow have to be milked?","Marty","Twice a day, ma'am, morning and evening - whose cows?","Caller - Jolene","The Hensleys, next farm over - forty head, I haven't seen the Hensleys since Saturday and the cows have been bawling","Caller - Jolene","You can hear it all night, they stand at the gate by the parlor where he lets them in - they all line up in the same order","Caller - Jolene","I went over there, I've never milked anything, I got about a coffee can out of one before she kicked it over","Caller - Jolene","I went back this morning, they were lined up again - same order, waiting on Mr. Hensley to open that gate","Marty","If the udders are hard and hot, open the gate to the pasture and let them go, ma'am - that's the kindest thing you can do","Caller - Jolene","I know, I know... I just didn't want to be the one that let them go","Marty","(Marty doesn't add anything)"}},
{"r4_sad_pin_curls","caller_story_sad",3,8,18,22,1,{"Caller - Faye","I do hair out of my house in Irvington - twenty-eight years, I've got the chair and the dryer hood in the front room","Marty","Go on, ma'am","Caller - Faye","Mrs. Pruitt has a standing Saturday, nine o'clock - wash and set, she came Saturday - walked over with her purse like nothing","Caller - Faye","She said her grandson was driving down from Louisville to fetch her, and she wanted to look decent for the car ride","Caller - Faye","No water pressure, so I washed her hair with a kettle - set it in rollers, did it right, took my time","Caller - Faye","She sat on my porch all afternoon waiting on him - then all evening","Caller - Faye","She slept sitting up in my chair that night, so she wouldn't muss the set","Caller - Faye","She's still here - Sunday I combed it out for her - Monday I set it again, we're on Tuesday's set now","Marty","(Marty doesn't answer, a truck passes outside the store)","Caller - Faye","If there's a young man coming from Louisville for Ada Pruitt, she looks real nice - tell him that"}},
{"r4_sad_pager_eggshell","caller_story_sad",3,8,19,23,1,{"Marty","We have somebody on - go ahead, you're on ninety-nine six","Caller - Sharon","Do you remember what the last thing your wife said to you was, Marty? Sorry - that's personal","Marty","I'm not married, ma'am - go ahead","Caller - Sharon","My husband and I had a thing with the pager - if he paged me a store's number, it meant call me there, I need you to decide something","Caller - Sharon","Friday afternoon he paged me the hardware store in West Point - so I knew he was standing in front of the paint chips","Caller - Sharon","We were doing the hall, I was at the sink with my hands wet, and I thought, I'll call him in a minute","Caller - Sharon","I'd already picked, it was eggshell, he wanted the one that was a little more yellow","Caller - Sharon","The number's still on the pager, I can scroll to it, that's all I've got left - that's the last thing he asked me","Marty","(Silence on the air for a while)","Caller - Sharon","Eggshell, if anybody asks"}},
{"r4_sad_fishing_license","caller_story_sad",3,8,10,21,1,{"Caller - Lyle","Marty, you can ask the county about fishing licenses? I mean, is there anybody to ask?","Marty","No, sir, there's nobody in that office - fish if you need to eat","Caller - Lyle","No, it's not that, my wife bought me a lifetime license for my sixtieth - that was April","Caller - Lyle","It's laminated, she had the lady at the courthouse laminate it, it's in my wallet with her picture","Caller - Lyle","She put a note in with it, said now you've got no excuse to be underfoot on Saturdays","Caller - Lyle","I went down to the creek today, first time since - sat there with the pole, didn't bait the hook","Caller - Lyle","I was just wondering if lifetime means mine or the state's","Marty","(Marty doesn't answer the question)","Caller - Lyle","Never mind that, you have a good night, Marty"}},
{"r4_sad_church_casserole","caller_story_sad",3,8,17,21,1,{"Caller - Darlene","I need to give somebody back their dish","Marty","Their dish, ma'am?","Caller - Darlene","When my mother passed in May, the church ladies brought food - everybody brought something, you know how it is","Caller - Darlene","I still have a glass dish with masking tape on the bottom - it says Vera Collins in ballpoint, green beans with the onions on top","Caller - Darlene","I kept meaning to wash it and take it back - it's been sitting clean in my cabinet since June","Caller - Darlene","Mrs. Collins was so kind to me, and I couldn't even get her dish back to her in six weeks","Caller - Darlene","If Vera Collins is out there, I've got your dish, I'm sorry it took me so long","Marty","(A pause)","Marty","She'll hear it, ma'am, or somebody who knows her will"}},
{"r4_sad_fourth_photos_undeveloped","caller_story_sad",3,8,18,22,1,{"Caller - Gail","I have a disposable camera from the Fourth of July - the cardboard kind - twenty-seven pictures","Caller - Gail","We took it to the family reunion at the lake - my dad took most of it, he kept forgetting to wind it, so half are probably the same one","Marty","Did you get them developed, ma'am?","Caller - Gail","No, it was going to go to the drugstore on Saturday - the one-hour place","Caller - Gail","Everybody who was at that reunion is on that little roll of film - thirty-one people","Caller - Gail","I don't know how many of those thirty-one are, anyway - I don't know","Caller - Gail","Does anybody know how to develop film without a store? Is that something a person can do?","Marty","Somebody will, if you know how, call this station - please","Marty","(The line holds open, neither of them says anything)"}},
{"r4_hor_seatbelts_lot","caller_story_horror",3,8,23,4,1,{"Caller - Mitch","I cut across the lot behind the warehouse in Muldraugh tonight - on foot, I was trying to get to my brother's","Caller - Mitch","Lot's full of cars, shift change Friday, I guess - half of them have the dome lights on, real dim, batteries almost gone","Marty","Were there people in them?","Caller - Mitch","Every one, sitting up in the driver's seat - Seatbelts on, facing straight ahead, like they're waiting at a light","Caller - Mitch","I thought they were dead, the regular kind - I thought, God help them, they just sat there and died","Caller - Mitch","I put my flashlight on the first windshield, and that one turned its head, then the next car, then the whole row","Caller - Mitch","They can't work the belts, Marty, that's what I figured out - they can't figure out a seatbelt, so they just sit there","Caller - Mitch","But they all knew where I was, all the way across the lot - heads turning, car to car, following me","Caller - Mitch","And the sound - hands on glass, forty cars of hands on glass","Marty","Stay off that lot - everybody - stay off the warehouse lot","Marty","(Marty exhales hard into the mic)","Marty","I parked in that lot - last year, for the county fair shuttle, I parked right in that lot"}},
{"r4_hor_deputy_open_carrier","caller_story_horror",3,8,1,4,1,{"Marty","Nobody's called in a while, I've got the police scanner on the desk, I want to tell you about something it's been doing","Marty","Every night since Monday, around ten after two, a sheriff's unit keys up - you hear the little chirp and then an open carrier - nobody talking","Marty","It's 4-Charlie-2, I know that because it's on the side of the car - deputy Hollingsworth, he buys horse wormer from me","Marty","Last night it keyed up and I heard something, I wrote it down so I'd get it right","Marty","A seat belt buckle hitting metal - click, click, over and over, like somebody's leg is swinging against it","Marty","Then a sound on the handset - like teeth, like somebody chewing on the cord","Scanner","(Chirp - open carrier, something taps the microphone twice)","Marty","That's it now, that's it keying up, it's ten after two","Marty","I'm turning the scanner down, I'm not turning it off, I can't turn it off, because what if he says something","Marty","(A long silence - Marty does not come back on until after three)"}},
{"r4_hor_dayroom_windows","caller_story_horror",3,8,23,4,1,{"Caller - Pam","I work, I worked second shift at the care home outside Rosewood - I drove past it tonight","Caller - Pam","There's a big dayroom on the front with the picture windows - it's where we'd park everybody for the television","Caller - Pam","The generator must still be going, the dayroom lights are on, it's the only lit thing for miles","Caller - Pam","All the wheelchairs are lined up at the windows - every chair - facing out, somebody rolled them there and put the brakes on","Marty","Were the residents in them?","Caller - Pam","Yes, and they're, they've all turned - I know every one of those faces - Mr. Deering - miss Lottie, they're pressed to the glass","Caller - Pam","But see, they couldn't have rolled themselves there, they can't work a brake, some of them couldn't when they were alive","Caller - Pam","Somebody on staff lined them up at those windows - on purpose - put the brakes on and turned on the lights and left","Caller - Pam","I keep thinking whoever did it wanted them to see the road - I don't know if that's kind or the worst thing I ever heard of","Marty","(Marty takes a long time to answer)","Marty","I don't know either, Pam - drive home - don't stop there"}},
{"r4_hor_music_box_truck","caller_story_horror",3,8,22,4,1,{"Caller - Scotty","You know the ice cream truck that does the subdivisions in Valley Station? The one with the music box speaker?","Marty","I know the kind","Caller - Scotty","It hit a pole Saturday on my street, the driver got out and ran - the music didn't stop, it's wired to the battery","Caller - Scotty","Day and night, that same little tune - it brought every one of them in the neighborhood, they're standing all around the truck","Caller - Scotty","But the battery's dying, so it's getting slower, every night it's slower and lower - like it's getting sleepy","Caller - Scotty","Tonight it's so slow it doesn't sound like a song anymore - just one note, and a long wait, and another note","Caller - Scotty","And the thing I can't stand is, every time a note comes, they all sway - all sixty of them - together","Marty","What happens when it stops?","Caller - Scotty","That's what I'm calling about, Marty, that's exactly what I'm calling about - they're going to need something else to listen to","Marty","Keep your house quiet, no lights, no radio speaker - use an earphone if you have one","Caller - Scotty","There, that was a note - I'm going","Marty","(Marty turns his own volume down so low the room goes silent)"}},
{"r4_hor_through_basement_door","caller_story_horror",3,7,22,2,1,{"Caller - Tommy","Hello - I'm Tommy - I'm eight, I know how to work the CB, my dad showed me","Marty","Hi, Tommy - I'm Marty - is there a grown-up with you?","Caller - Tommy","My dad's in the basement, he went down there Sunday after he got hurt, he told me lock the door and don't open it","Marty","That's good, that was good advice - are you keeping it locked?","Caller - Tommy","Yes, I eat cereal with no milk - I sleep on the couch, I talk to him through the door so he's not lonely","Caller - Tommy","He doesn't talk back, but he scratches back - when I scratch the door, he scratches","Marty","Tommy - listen to me real careful - don't open that door, not for anything - do you hear me, buddy?","Caller - Tommy","I know, he said not to, I'm just calling because the scratching's been a lot tonight and I want to know when he's going to feel better","Marty","Is there a neighbor? Anybody you know? Anybody with a porch light?","Caller - Tommy","No, I have to go - I'm not supposed to use up the battery","Marty","Tommy? Tommy, tell me your road - Tommy","Marty","(No answer - Marty stays on the channel calling the boy's name, quieter each time)"}},
{"r4_hor_trailer_underneath","caller_story_horror",3,8,0,4,1,{"Caller - Crystal","I'm in a single-wide in the park off the March Ridge road. Been in bed since dark. I'm not putting my feet on that floor","Marty","What's happened?","Caller - Crystal","The skirting's torn on one side, around eleven, the floor under my bed bumped, like a knee - like somebody sitting up under there","Caller - Crystal","I got up and went to the kitchen - real quiet, stood on the linoleum","Caller - Crystal","And a minute later, the floor bumped under the kitchen - right under my feet, it followed me","Caller - Crystal","It's dragging itself on its back under there. I can hear the insulation tearing. I can hear it breathing, Marty, through the floor","Marty","Is your car close? Could you get to the car?","Caller - Crystal","Car's at the door, but the steps are the part that's open, the torn part is right by the steps","Caller - Crystal","I'm back on the bed. I'm staying here. Every time I move it bumps under me, so I... I'm not moving","Marty","(Marty says okay three times, softly, and then nothing at all)"}},
{"r4_hor_church_bell_barricade","caller_story_horror",3,8,23,4,1,{"Caller - Lonnie","Marty - you hear the bell in Rosewood? The Baptist church, the one with the real bell tower","Marty","I'm too far off - what about it?","Caller - Lonnie","It rings at night, not on the hour - once, then maybe six minutes - then once, it's been going since Sunday night","Caller - Lonnie","I figured somebody was in there - signaling, so tonight I went and banged on the church doors","Caller - Lonnie","The front doors are nailed shut, from the inside, you can see the nail points come through the wood","Caller - Lonnie","I went around back to the tower door - also nailed, and there's a note taped on the inside of the glass, facing out","Marty","What did it say?","Caller - Lonnie","It said we are all together in here - please don't let us out, signed by the pastor - dated Sunday","Caller - Lonnie","And while I was reading it, the bell rang, right over my head - one time","Marty","(Marty doesn't speak, when he does, his voice has gone thin)","Marty","Leave it be, Lonnie, leave those doors the way they are"}},
}
